function readingFormat([name, project, city, aim], index, source) {
  const venues = ["the community hall", "the library meeting room", "the riverside centre", "the college studio", "the museum workshop", "the school activity room", "the sports pavilion", "the university foyer", "the town information office", "the bookshop upstairs room"];
  const venue = venues[index];
  const optionOrder = seed => { const values = [0, 1, 2]; const shift = (index + seed) % 3; return values.map((_, i) => values[(i + shift) % 3]); };
  const part1 = {
    message: `Hello everyone, the next ${project} session in ${city} will take place on Thursday at 6:30 p.m. We will meet at ${venue}. Please confirm by Tuesday and bring a notebook. If you can no longer attend, email ${name} so another person can use your place.`,
    items: [
      { prompt: `The next ${project} meeting in ${city} will be held on ___.`, options: ["Thursday", "Friday", "Saturday"], correct: 0 },
      { prompt: `Participants should meet for ${project} at ___.`, options: [venue, "The main railway station", "The central market"], correct: 0 },
      { prompt: `People should confirm their place for ${project} by ___.`, options: ["Tuesday", "Thursday evening", "The following Monday"], correct: 0 },
      { prompt: `Visitors to the ${project} session should bring ___.`, options: ["A notebook", "A packed lunch", "A printed photograph"], correct: 0 },
      { prompt: `A person who cannot attend ${project} should email ___.`, options: [name, "The bus station manager", "The college principal"], correct: 0 }
    ]
  };
  part1.items.forEach(item => {
    const order = optionOrder(part1.items.indexOf(item));
    item.options = order.map(i => item.options[i]);
    item.correct = order.indexOf(item.correct);
  });
  const sequenceTexts = [
    [
      `Residents in ${city} began discussing ${project} after noticing a need connected with ${aim}.`,
      "After those discussions, a small planning group met and listed what help, time and equipment would be needed.",
      "Once that list was complete, the planning group invited local people to share skills and suggest a suitable venue.",
      "After receiving those suggestions, the organisers arranged one trial session so they could test the plan on a small scale.",
      "After the trial, participants described which parts were useful and which were confusing.",
      "The group used those comments to prepare a clearer programme for future sessions."
    ],
    [
      `The ${project} organisers announced a new session several weeks before it was due to happen.`,
      "The announcement gave two possible dates and asked participants to choose the one most people could attend.",
      "Once the date was agreed, volunteers divided the practical jobs between them.",
      `After the jobs had been assigned, the team confirmed ${venue} and sent everyone directions before the event.`,
      "On the day, the volunteers arrived early and prepared the room together.",
      "After the session, they wrote down suggestions to improve the next event."
    ]
  ];
  const sequenceOrders = [[0, 3, 1, 5, 2, 4], [0, 4, 2, 5, 1, 3]];
  const part2 = sequenceTexts.map((ordered, taskIndex) => {
    const scrambledIndexes = sequenceOrders[taskIndex];
    const correctPositions = Array(ordered.length);
    scrambledIndexes.forEach((sentenceIndex, position) => { correctPositions[sentenceIndex] = position + 1; });
    return { title: taskIndex === 0 ? `How ${project} began` : `Preparing the next ${project} session`, sentences: scrambledIndexes.map(sentenceIndex => ordered[sentenceIndex]), correctPositions };
  });
  const people = [
    { id: "p1", name: ["Alex", "Sara", "Nina", "Omar", "Leah", "Victor", "Mina", "Felix", "Amira", "Theo"][index], text: `I joined ${project} because I wanted to meet people nearby. Working together has been the most useful part for me. The organisers should keep some activities practical so people can learn directly from one another.` },
    { id: "p2", name: ["Ravi", "Imran", "Chloe", "Marta", "Jonah", "Mei", "Daniel", "Aisha", "Ruben", "Ivy"][index], text: `I help organise ${project}. The sessions work best when people know exactly where to go and what to bring. I would like us to share a short online guide as well, especially for anyone who cannot attend the first meeting.` },
    { id: "p3", name: ["Grace", "Chloe", "Ethan", "Priya", "Noah", "Luis", "Hana", "George", "Zara", "Ben"][index], text: `I support the aim of ${project}, but I do not think the group should expand immediately. First, it needs to check whether the current times and venue are accessible to different residents and whether the sessions are having the intended effect.` },
    { id: "p4", name: ["Owen", "Max", "Ella", "Samir", "Ruby", "Nora", "Eli", "Luca", "Freya", "Tariq"][index], text: `Before I tried ${project}, I assumed it would not be useful to me. After attending once, I changed my mind and found it welcoming. I now recommend it to friends, although I think new participants should receive a simple introduction first.` }
  ];
  const part3 = {
    topic: `Four people give their views on ${project} in ${city}.`, people,
    statements: [
      { text: `This person values learning directly from other local participants in ${project}.`, correct: "p1" },
      { text: `This person would like a guide for people who cannot attend the first ${project} meeting.`, correct: "p2" },
      { text: `This person wants to check access and results before ${project} expands.`, correct: "p3" },
      { text: `This person changed their opinion after taking part in ${project}.`, correct: "p4" },
      { text: `This person says the practical activities are an important benefit of ${project}.`, correct: "p1" },
      { text: `This person has an organising role in ${project}.`, correct: "p2" },
      { text: `This person recommends giving newcomers an introduction to ${project}.`, correct: "p4" }
    ]
  };
  const headings = [
    { id: "h1", text: `Recognising a need in ${city}` }, { id: "h2", text: "Testing the idea before expanding" },
    { id: "h3", text: "Making participation easier to access" }, { id: "h4", text: "Combining local skills and resources" },
    { id: "h5", text: "Benefits beyond the original aim" }, { id: "h6", text: "Finding evidence of lasting value" },
    { id: "h7", text: "Planning growth without losing quality" }, { id: "h8", text: "Why the project should be replaced by a commercial service" }
  ];
  const sample = `In ${city}, the idea for ${project} grew from conversations among residents. People wanted a practical response to ${aim}, but they were unsure whether a small local group could make a lasting difference. Rather than launch a large programme immediately, the organisers decided to learn from the people who might use it.`;
  const paragraphs = [
    { heading: "h1", text: `The need was not identified from a national report but from repeated local conversations. Residents described how ${aim} affected ordinary routines and pointed out that existing services did not always fit their circumstances. The organisers compared these accounts and looked for a manageable first step. Their aim was not to claim that one community project could solve a broad problem. Instead, they wanted to offer a useful local response, learn what worked and invite participants to shape the next stage. This careful beginning helped the group explain its purpose without promising more than it could deliver.` },
    { heading: "h2", text: `The first version of ${project} was deliberately small. A limited trial allowed the team to check the venue, timing and instructions before inviting a much larger audience. Participants were asked what had been clear and what had caused difficulty. Some suggestions were simple, such as changing the order of activities or sending directions earlier, while others required more planning. The organisers made a short list of changes and tested them at the next session. This approach took longer than announcing a full programme at once, but it reduced the risk of repeating avoidable mistakes and gave local people a reason to trust the project.` },
    { heading: "h3", text: `Making an activity available does not automatically make it accessible. The team therefore considered cost, travel, information and the needs of people who had not attended before. A session that works for someone with a flexible schedule may be difficult for a person with caring duties or a long journey. The organisers began sharing basic information in advance and asked participants to identify practical barriers privately. They also discussed whether some material could be offered online, while recognising that digital access is not equal for everyone. These adjustments were modest, but they made it easier for more residents to decide whether the activity suited them.` },
    { heading: "h4", text: `The project depended on more than enthusiasm. Local partners contributed time, space or specialist knowledge, and volunteers had to coordinate those contributions carefully. The group tried to make responsibilities clear so that the same people were not expected to solve every problem. When a partner could not help on a particular date, the organisers adjusted the plan instead of cancelling without explanation. This network of support gave ${project} access to resources it could not have paid for alone. It also created a shared sense of responsibility: residents were not simply receiving a service but helping to maintain something they valued.` },
    { heading: "h5", text: `Participants sometimes described benefits that were not part of the original plan. People met neighbours they had not spoken to before, exchanged advice and became more confident about contributing to other local activities. Such outcomes are difficult to measure, yet they can affect whether a project remains useful over time. The organisers did not treat these comments as proof that every participant had the same experience. Instead, they used them as prompts for further questions. The wider value of ${project} may therefore include both its direct response to ${aim} and the relationships that develop while people work toward a shared goal.` },
    { heading: "h6", text: `The team wanted to know whether the work was making a difference, not simply whether an event had taken place. It began recording attendance, repeat visits and the questions people raised. These figures could show patterns, but they could not explain why someone stopped coming or whether the activity had helped them outside the session. For that reason, the group combined simple records with short feedback conversations. It reviewed the evidence at regular intervals and avoided presenting early results as a final verdict. This made evaluation part of the project rather than a report written only when funding or publicity was needed.` },
    { heading: "h7", text: `The next stage is to decide how ${project} can continue without losing the qualities participants appreciate. Some residents would welcome more sessions, while others worry that rapid growth could make the activity less personal or harder to organise. The team plans to compare different options, including training additional volunteers and working with another venue in ${city}. Any expansion will depend on whether suitable support is available and whether the existing group can maintain clear communication. The organisers see sustainable progress as a series of informed decisions, not a promise to grow every year. Their central measure will remain whether the project responds to real local needs.` }
  ];
  const headingOrder = ["h6", "h2", "h8", "h1", "h7", "h4", "h3", "h5"];
  const shuffledHeadings = headingOrder.map(id => headings.find(heading => heading.id === id));
  return { part1, part2, part3, part4: { sample, paragraphs, headings: shuffledHeadings } };
}

function listeningFormat([name, project, city, aim], index) {
  const people = [
    ["Maya", "Daniel", "Priya", "Owen", "Clara", "Hassan", "Nora", "Ethan", "Zara", "Ben"],
    ["Liam", "Aisha", "Tom", "Grace", "Luis", "Mina", "Jon", "Ravi", "Ella", "Mei"],
    ["Rosa", "Adam", "Leah", "Imran", "Sophie", "Noah", "Amir", "Chloe", "Felix", "Ivy"]
  ];
  const contact = people.map(set => set[index]);
  const part1 = { items: [
    { transcript: `Hello, this is ${name}. The ${project} meeting has moved to Saturday morning at ten, not Friday afternoon.`, prompt: `When will the next ${project} meeting take place?`, options: ["Saturday at 10 a.m.", "Friday at 10 a.m.", "Saturday at 2 p.m."], correct: 0 },
    { transcript: `For the ${project} session in ${city}, please use the side entrance beside the garden. The front door will be locked.`, prompt: `Which entrance should participants use for ${project}?`, options: ["The side entrance by the garden", "The front door", "The entrance beside the car park"], correct: 0 },
    { transcript: `A quick update about ${project}: the meeting room is unavailable on Tuesday, so the session will be held on Wednesday evening instead.`, prompt: `Why has the ${project} session changed to Wednesday?`, options: ["The room is unavailable on Tuesday", "The organiser is travelling", "The session needs more equipment"], correct: 0 },
    { transcript: `Before coming to ${project}, remember to bring a notebook. The organisers will provide pens and all other materials.`, prompt: `What should a participant bring to ${project}?`, options: ["A notebook", "Pens", "All the materials"], correct: 0 },
    { transcript: `If you can no longer attend ${project}, please email ${contact[0]} before Tuesday so the waiting list can be contacted.`, prompt: `How should someone cancel their place at ${project}?`, options: [`Email ${contact[0]} before Tuesday`, "Telephone the venue on the day", "Message the other participants"], correct: 0 }
  ] };
  const part2 = {
    speakers: [
      { id: "s1", name: contact[0], transcript: `I joined ${project} because I want to meet people who live nearby. I already spend a lot of time working alone, so the chance to share ideas in person is what appeals to me most.` },
      { id: "s2", name: contact[1], transcript: `My main reason for joining ${project} is to gain practical experience. I hope an experienced volunteer can show me the basics before I try to do things independently.` },
      { id: "s3", name: contact[2], transcript: `I am interested in ${project}, but I can only attend at weekends because of my work schedule. A flexible timetable is the most important thing for me.` },
      { id: "s4", name: ["Elena", "Marco", "Isabel", "Dylan", "Anika", "Oscar", "Sofia", "Leila", "Nathan", "Ella"][index], transcript: `I offered to help with ${project} because I have some useful equipment at home. I can lend it to the group, provided it is returned in good condition after each session.` }
    ],
    options: [
      { id: "o1", text: "Wants to meet and exchange ideas with local people" }, { id: "o2", text: "Wants guidance before trying a new skill" },
      { id: "o3", text: "Needs sessions to fit a weekend schedule" }, { id: "o4", text: "Can lend useful equipment to the group" },
      { id: "o5", text: "Would prefer to work alone" }, { id: "o6", text: "Is mainly looking for a paid position" }
    ], matches: { s1: "o1", s2: "o2", s3: "o3", s4: "o4" }
  };
  const part3 = {
    speakers: [{ id: "a", name: contact[0] }, { id: "b", name: contact[1] }],
    transcript: `Interviewer: Should ${project} add more sessions? ${contact[0]}: I would like it to reach more people, but expanding too quickly could make it harder to keep the activities welcoming. We should train another volunteer first. ${contact[1]}: I agree about welcoming people, but I would keep the current schedule. More sessions are not helpful if newcomers do not know what to expect. A short introduction would make a bigger difference. ${contact[0]}: That is fair; clear information should come before advertising.`,
    statements: [
      { text: `This speaker thinks the group should prepare another volunteer before expanding ${project}.`, correct: "a" },
      { text: `This speaker would rather improve the introduction than add sessions for ${project}.`, correct: "b" },
      { text: `This speaker wants to keep the current schedule for ${project} rather than add more sessions.`, correct: "b" },
      { text: `This speaker is concerned that rapid expansion could affect the welcoming atmosphere of ${project}.`, correct: "a" }
    ]
  };
  const part4 = [
    {
      title: `A participant reflects on ${project}`,
      transcript: `When I first heard about ${project} in ${city}, I thought it would be mainly about ${aim}. I was surprised that the organisers spent time asking what participants actually needed. I found the practical demonstration most useful because I could try the process instead of only hearing an explanation. The difficult part was arranging the journey after work, so I would like clearer information about session times. I plan to return because the group was friendly and I learned something I can use outside the meeting.`,
      items: [
        { prompt: `What did the speaker find most useful about ${project}?`, options: ["Trying a practical activity", "Listening to a long presentation", "Receiving a travel discount"], correct: 0 },
        { prompt: `What would make it easier for the speaker to attend ${project}?`, options: ["Clearer information about times", "A different project topic", "A larger group"], correct: 0 }
      ]
    },
    {
      title: `The organiser's view of ${project}`,
      transcript: `As an organiser of ${project}, I used to think that finding a suitable venue would be our main challenge. In fact, keeping communication clear has required more attention. Feedback showed that some residents were unsure what to bring, so we now send a short checklist in advance. We have not decided to run sessions every week; first we want to see whether volunteers can support the current programme. If the next review shows that people are benefiting and the team has enough help, we may add one extra session later in the year.`,
      items: [
        { prompt: `What change did feedback lead the ${project} team to make?`, options: ["Send a checklist before sessions", "Hold meetings every week", "Change to a different venue"], correct: 0 },
        { prompt: `What will determine whether ${project} adds another session?`, options: ["Evidence of benefit and enough volunteer support", "A request from one participant", "The availability of new equipment"], correct: 0 }
      ]
    }
  ];
  const audioClips = {};
  part1.items.forEach((item, i) => { item.clipId = `l1-${i + 1}`; audioClips[item.clipId] = item.transcript; });
  part2.speakers.forEach(speaker => { speaker.clipId = `l2-${speaker.id}`; audioClips[speaker.clipId] = speaker.transcript; });
  part3.clipId = "l3-dialogue"; audioClips[part3.clipId] = part3.transcript;
  part4.forEach((monologue, i) => { monologue.clipId = `l4-${i + 1}`; audioClips[monologue.clipId] = monologue.transcript; });
  return { part1, part2, part3, part4, audioClips };
}


